#define CJK_COUNT 124

const uint16_t *font_cjk_glyph(uint32_t cp)
{
    for (int i = 0; i < CJK_COUNT; i++)
        if (cjk_cp[i] == cp) return cjk_glyphs[i];
    return NULL;
}
